import{_ as n,a0 as p,w as u,s as l,ao as r,I as o,a1 as s,A as i,x as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const I=JSON.parse('{"title":"如何在 Ubuntu 上用 Go For It 管理您的待办清单 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 上用 Go For It 管理您的待办清单 | LCTT (201511) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 上用 Go For It 管理您的待办清单 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 上用 Go For It 管理您的待办清单 | LCTT (201511) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201511/20151105 How to Manage Your To-Do Lists in Ubuntu Using Go For It Application","title":"如何在 Ubuntu 上用 Go For It 管理您的待办清单","tag":"201511","desc":""},"relativePath":"201511/20151105 How to Manage Your To-Do Lists in Ubuntu Using Go For It Application.md","filePath":"[post].md"}'),m={name:"201511/20151105 How to Manage Your To-Do Lists in Ubuntu Using Go For It Application.md"};function d(f,t,g,w,b,T){const a=p("Link");return u(),l("div",null,[t[18]||(t[18]=r('<h1 id="如何在-ubuntu-上用-go-for-it-管理您的待办清单" tabindex="-1">如何在 Ubuntu 上用 Go For It 管理您的待办清单 <a class="header-anchor" href="#如何在-ubuntu-上用-go-for-it-管理您的待办清单" aria-label="Permalink to “如何在 Ubuntu 上用 Go For It 管理您的待办清单”">​</a></h1><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/gfi-featured1.jpg" alt=""></p><p>任务管理可以说是工作及日常生活中最重要也最具挑战性的事情之一。当您在工作中承担越来越多的责任时，您的表现将与您管理任务的能力直接挂钩。</p><p>若您的工作有部分需要在电脑上完成，那么您一定很乐意知道，有多款应用软件自称可以为您减轻任务管理的负担。即便这些软件中的大多数都是为 Windows 用户服务的，在 Linux 系统中仍然有不少选择。在本文中，我们就来讨论这样一款软件：Go For It.</p><h3 id="go-for-it" tabindex="-1">Go For It <a class="header-anchor" href="#go-for-it" aria-label="Permalink to “Go For It”">​</a></h3>',5)),o("p",null,[s(a,{href:"http://manuel-kehl.de/projects/go-for-it/"},{default:i(()=>[...t[0]||(t[0]=[e("Go For It",-1)])]),_:1}),t[1]||(t[1]=e(" (GFI) 由 Manuel Kehl 开发，他声称：“这是款简单易用且时尚优雅的生产力软件，以待办清单（To-Do List）为主打特色，并整合了一个能让你专注于当前事务的定时器。”这款软件的定时器功能尤其有趣，它还可以让您在继续工作之前暂停下来，放松一段时间。",-1))]),t[19]||(t[19]=r(`<h3 id="下载并安装" tabindex="-1">下载并安装 <a class="header-anchor" href="#下载并安装" aria-label="Permalink to “下载并安装”">​</a></h3><p>使用基于 Debian 系统（如Ubuntu）的用户可以通过运行以下终端命令轻松地安装这款软件：</p><pre><code>sudo add-apt-repository ppa:mank319/go-for-it
sudo apt-get update
sudo apt-get install go-for-it
</code></pre><p>以上命令执行完毕后，您就可以使用这条命令运行这款应用软件了：</p><pre><code>go-for-it
</code></pre><h3 id="使用及配置" tabindex="-1">使用及配置### <a class="header-anchor" href="#使用及配置" aria-label="Permalink to “使用及配置###”">​</a></h3><p>当你第一次运行 GFI 时，它的界面是长这样的：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/gfi-first-run1.png" alt="gfi-first-run"></p><p>可以看到，界面由三个标签页组成，分别是<em>待办</em> (To-Do)，<em>定时器</em> (Timer)和<em>完成</em> (Done)。<em>待办</em>页是一个任务列表（上图所示的4个任务是默认生成的——您可以点击头部的方框删除它们），<em>定时器</em>页内含有任务定时器，而<em>完成</em>页则是已完成任务的列表。底部有个文本框，您可以在此输入任务描述，并点击“+”号将任务添加到上面的列表中。</p><p>举个例子，我将一个名为“MTE-research-work”的任务添加到了列表中，并点击选中了它，如下图所示：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/gfi-task-added1.png" alt="gfi-task-added"></p><p>然后我进入<em>定时器</em>页，在这里我可以看到一个为当前“MTE-reaserch-work”任务设定的定时器，定时25分钟。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/gfi-active-task-timer.png" alt="gfi-active-task-timer"></p><p>当然，您可以将定时器设定为你喜欢的任何值。然而我并没有修改，而是直接点击下方的“开始 (Start)”按钮启动定时器。一旦剩余时间为60秒，GFI 就会给出一个提示。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/gfi-first-notification-new.jpg" alt="gfi-first-notification-new"></p><p>一旦时间到，它会提醒我休息5分钟。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/gfi-time-up-notification-new.jpg" alt="gfi-time-up-notification-new"></p><p>5分钟过后，我可以为我的任务再次开启定时器。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/gfi-break-time-up-new.jpg" alt="gfi-break-time-up-new"></p><p>任务完成以后，您可以点击<em>定时器</em>页中的“完成 (Done)”按钮，然后这个任务就会从<em>待办</em>页被转移到<em>完成</em>页。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/gfi-task-done1.png" alt="gfi-task-done"></p><p>GFI 也能让您稍微调整一些它的设置。例如，下图所示的设置窗口就包含了一些选项，让您修改默认的任务时长，休息时长和提示时刻。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/gfi-settings1.png" alt="gfi-settings"></p>`,23)),o("p",null,[t[3]||(t[3]=e("值得一提的是，GFI 是以 TODO.txt 格式保存待办清单的，这种格式方便了移动设备之间的同步，也让您能使用其他前端程序来编辑任务——更多详情请阅读",-1)),s(a,{href:"http://todotxt.com/"},{default:i(()=>[...t[2]||(t[2]=[e("这里",-1)])]),_:1}),t[4]||(t[4]=e("。",-1))]),t[20]||(t[20]=o("p",null,"您还可以通过以下视频观看 GFI 的动态展示。",-1)),t[21]||(t[21]=o("p",null,"注：youtube 视频",-1)),t[22]||(t[22]=o("iframe",{frameborder:"0",src:"http://www.youtube.com/embed/mnw556C9FZQ?autoplay=1&autohide=2&border=1&wmode=opaque&enablejsapi=1&controls=1&showinfo=0",id:"youtube-iframe"},null,-1)),t[23]||(t[23]=o("h3",{id:"结论",tabindex:"-1"},[e("结论### "),o("a",{class:"header-anchor",href:"#结论","aria-label":"Permalink to “结论###”"},"​")],-1)),t[24]||(t[24]=o("p",null,"正如您所看到的，GFI 是一款简洁明了且易于使用的任务管理软件。虽然它没有提供非常丰富的功能，但它实现了它的承诺，定时器的整合特别有用。如果您正在寻找一款实现了基础功能，并且开源的 Linux 任务管理软件，Go For It 值得您一试。",-1)),t[25]||(t[25]=o("hr",null,null,-1)),o("p",null,[t[6]||(t[6]=e("via: ",-1)),s(a,{href:"https://www.maketecheasier.com/to-do-lists-ubuntu-go-for-it/"},{default:i(()=>[...t[5]||(t[5]=[e("https://www.maketecheasier.com/to-do-lists-ubuntu-go-for-it/",-1)])]),_:1})]),o("p",null,[t[10]||(t[10]=e("作者：",-1)),s(a,{href:"https://www.maketecheasier.com/author/himanshu/"},{default:i(()=>[...t[7]||(t[7]=[e("Himanshu Arora",-1)])]),_:1}),t[11]||(t[11]=e(" 译者：",-1)),s(a,{href:"https://github.com/Ricky-Gong"},{default:i(()=>[...t[8]||(t[8]=[e("Ricky-Gong",-1)])]),_:1}),t[12]||(t[12]=e(" 校对：",-1)),s(a,{href:"https://github.com/carolinewuyan"},{default:i(()=>[...t[9]||(t[9]=[e("Caroline",-1)])]),_:1})]),o("p",null,[t[15]||(t[15]=e("本文由 ",-1)),s(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[13]||(t[13]=[e("LCTT",-1)])]),_:1}),t[16]||(t[16]=e(" 原创编译，",-1)),s(a,{href:"https://linux.cn/"},{default:i(()=>[...t[14]||(t[14]=[e("Linux中国",-1)])]),_:1}),t[17]||(t[17]=e(" 荣誉推出",-1))])])}const G=n(m,[["render",d]]);export{I as __pageData,G as default};
